// hashline_test.go — covers the Go half of the hashline contract.
//
// TestHashlineGoldenVector is the parity anchor: the digests come from
// testdata/hashline_golden.json, generated by the TypeScript implementation
// (pi-extension/hashline.ts) and asserted by `bun test` as well. If this test
// fails, the backend would resolve different anchors than the extension writes
// — i.e. the approved diff would not be the written bytes.

const hashlineSample = "alpha\nbeta\ngamma\nduplicate\nduplicate\n"

func hl(s string) string { return hashLine(s, hashMinLength) }

func TestHashlineGoldenVector(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "hashline_golden.json"))
	if err != nil {
		t.Fatalf("read golden vector: %v", err)
	}
	var golden struct {
		HashLength     int `json:"hashLength"`
		FullHashLength int `json:"fullHashLength"`
		Cases          []struct {
			Line string `json:"line"`
			Hash string `json:"hash"`
			Full string `json:"full"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatalf("parse golden vector: %v", err)
	}
	if len(golden.Cases) == 0 {
		t.Fatal("golden vector is empty")
	}
	for i, c := range golden.Cases {
		if got := hashLine(c.Line, golden.HashLength); got != c.Hash {
			t.Errorf("case %d (%q): hash = %q, want %q", i, c.Line, got, c.Hash)
		}
		if got := hashLine(c.Line, golden.FullHashLength); got != c.Full {
			t.Errorf("case %d (%q): full hash = %q, want %q", i, c.Line, got, c.Full)
		}
	}
}

func TestHashlineAlphabet(t *testing.T) {
	if len(hashAlphabet) != 32 {
		t.Errorf("alphabet has %d characters, want 32", len(hashAlphabet))
	}
	for _, banned := range []rune{'i', 'l', 'o', 'u'} {
		if strings.ContainsRune(hashAlphabet, banned) {
			t.Errorf("alphabet must exclude %q (ambiguous in copied text)", banned)
		}
	}
	// Line endings never change a digest: CRLF files hash like LF files.
	if hashLine("x", hashMinLength) != hashLine("x\r", hashMinLength) {
		t.Error("CRLF line must hash like its LF form")
	}
}

func TestHashlineDocRoundTrip(t *testing.T) {
	for _, content := range []string{"", "a", "a\n", "a\nb", "a\nb\n", "a\n\n", "a\r\nb\r\n", "\n", "\n\n", "a\n\nb\n"} {
		if got := splitHashlineDoc(content).join(); got != content {
			t.Errorf("round trip %q produced %q", content, got)
		}
	}
}

func TestHashlineSplitLines(t *testing.T) {
	cases := []struct {
		content string
		want    int
	}{
		{"", 0},
		{"a\nb\n", 2}, // a trailing newline is not a line
		{"a\nb", 2},
		{"a\n\n", 2}, // a real blank line IS addressable
		{"\n", 1},
	}
	for _, c := range cases {
		if got := len(splitHashlineDoc(c.content).lines); got != c.want {
			t.Errorf("split %q produced %d lines, want %d", c.content, got, c.want)
		}
	}
	doc := splitHashlineDoc("a\r\nb\n")
	if len(doc.crs) != 2 || !doc.crs[0] || doc.crs[1] {
		t.Errorf("CRLF flags = %v, want [true false]", doc.crs)
	}
}

func TestHashlineResolve(t *testing.T) {
	doc := splitHashlineDoc(hashlineSample)

	if got, err := resolveHashline(doc, hl("gamma"), "hash", 1); err != nil || got != 2 {
		t.Fatalf("resolve gamma = %d, %v; want 2", got, err)
	}
	// Hashes are copied text, so uppercase input still resolves a unique line…
	if got, err := resolveHashline(doc, strings.ToUpper(hl("gamma")), "hash", 1); err != nil || got != 2 {
		t.Errorf("uppercase resolve = %d, %v; want 2", got, err)
	}
	// …and an uppercase hash of a duplicated line is still refused.
	if got, err := resolveHashline(doc, strings.ToUpper(hl("duplicate")), "hash", 1); err == nil {
		t.Fatalf("duplicated line resolved to %d; want an ambiguity error", got)
	} else if !strings.Contains(err.Error(), "ambiguous") {
		t.Fatalf("expected ambiguity error, got %v", err)
	}

	for _, tc := range []struct {
		name string
		hash string
		want string
	}{
		{"stale", "0000", "no line matches"},
		{"alphabet", "oooo", "hash alphabet"},
		{"too short", "abc", "must be 4-12 characters"},
		{"too long", strings.Repeat("a", 13), "must be 4-12 characters"},
		{"empty", "", "is empty"},
	} {
		if _, err := resolveHashline(doc, tc.hash, "hash", 7); err == nil || !strings.Contains(err.Error(), tc.want) {
			t.Errorf("%s: resolve(%q) error = %v, want it to contain %q", tc.name, tc.hash, err, tc.want)
		} else if !strings.Contains(err.Error(), "edit 7") {
			t.Errorf("%s: error must name the edit: %v", tc.name, err)
		}
	}

	// A duplicated line names every candidate so the agent can pick one.
	_, err := resolveHashline(doc, hl("duplicate"), "hash", 1)
	if err == nil || !strings.Contains(err.Error(), "line 4") || !strings.Contains(err.Error(), "line 5") {
		t.Errorf("ambiguity error must list both lines: %v", err)
	}

	// Identical duplicates share every digest bit, so no hash length disambiguates them.
	if got, err := resolveHashline(doc, hashLine("duplicate", hashMaxLength), "hash", 1); err == nil {
		t.Errorf("identical duplicates must stay ambiguous even at %d chars (resolved to %d)", hashMaxLength, got)
	}
	if got, err := resolveHashline(doc, hashLine("gamma", hashMaxLength), "hash", 1); err != nil || got != 2 {
		t.Errorf("full-length hash for a unique line = %d, %v; want 2", got, err)
	}
}

func TestApplyHashlineEdit(t *testing.T) {
	cases := []struct {
		name  string
		in    string
		edit  hashlineEdit
		want  string
		errAt string
	}{
		{"replace", hashlineSample, hashlineEdit{Hash: hl("beta"), NewText: "BETA"},
			"alpha\nBETA\ngamma\nduplicate\nduplicate\n", ""},
		{"range", hashlineSample, hashlineEdit{Hash: hl("alpha"), EndHash: hl("gamma"), NewText: "x\ny"},
			"x\ny\nduplicate\nduplicate\n", ""},
		{"delete drops the newline", hashlineSample, hashlineEdit{Hash: hl("gamma"), NewText: ""},
			"alpha\nbeta\nduplicate\nduplicate\n", ""},
		{"delete every line empties the file", "solo\n", hashlineEdit{Hash: hl("solo"), NewText: ""}, "", ""},
		{"insert before", hashlineSample, hashlineEdit{Hash: hl("gamma"), Insert: "before", NewText: "above"},
			"alpha\nbeta\nabove\ngamma\nduplicate\nduplicate\n", ""},
		{"insert after", hashlineSample, hashlineEdit{Hash: hl("gamma"), Insert: "after", NewText: "below"},
			"alpha\nbeta\ngamma\nbelow\nduplicate\nduplicate\n", ""},
		{"trailing newline is a terminator", hashlineSample, hashlineEdit{Hash: hl("gamma"), NewText: "gamma\n"},
			hashlineSample, ""},
		{"no final newline stays without one", "a\nb", hashlineEdit{Hash: hl("b"), NewText: "B"}, "a\nB", ""},
		{"CRLF replacement keeps endings", "one\r\ntwo\r\n", hashlineEdit{Hash: hl("two"), NewText: "TWO"},
			"one\r\nTWO\r\n", ""},
		{"CRLF insert keeps endings", "one\r\ntwo\r\n",
			hashlineEdit{Hash: hl("two"), Insert: "after", NewText: "three\nfour"}, "one\r\ntwo\r\nthree\r\nfour\r\n", ""},
		{"ambiguous duplicate", hashlineSample, hashlineEdit{Hash: hl("duplicate"), NewText: "x"}, "", "ambiguous"},
		{"stale hash", hashlineSample, hashlineEdit{Hash: "0000", NewText: "x"}, "", "no line matches"},
		{"endHash before hash", hashlineSample,
			hashlineEdit{Hash: hl("gamma"), EndHash: hl("alpha"), NewText: "x"}, "", "before the anchor line"},
		{"insert with endHash", hashlineSample,
			hashlineEdit{Hash: hl("alpha"), EndHash: hl("gamma"), Insert: "after", NewText: "x"}, "", "cannot be combined"},
		{"insert with empty newText", hashlineSample,
			hashlineEdit{Hash: hl("alpha"), Insert: "after", NewText: ""}, "", "inserts nothing"},
		{"empty file has no anchor", "", hashlineEdit{Hash: hl("x"), NewText: "x"}, "", "legacy edit"},
	}

	for _, tc := range cases {
		got, err := applyHashlineEdit(tc.in, tc.edit, 3)
		if tc.errAt != "" {
			if err == nil || !strings.Contains(err.Error(), tc.errAt) {
				t.Errorf("%s: error = %v, want it to contain %q", tc.name, err, tc.errAt)
			}
			continue
		}
		if err != nil {
			t.Errorf("%s: unexpected error %v", tc.name, err)
			continue
		}
		if got != tc.want {
			t.Errorf("%s:\n got %q\nwant %q", tc.name, got, tc.want)
		}
	}
}

// TestApplyHashlineEditsSurviveShift is the property hashline anchors exist for:
// an earlier edit that shifts line numbers must not move a later anchor.
func TestApplyHashlineEditsSurviveShift(t *testing.T) {
	got, err := applyEdits(hashlineSample, []editPair{
		{Hash: hl("alpha"), Insert: "after", NewText: "a1\na2"},
		{Hash: hl("gamma"), NewText: "GAMMA"},
	})
	want := "alpha\na1\na2\nbeta\nGAMMA\nduplicate\nduplicate\n"
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != want {
		t.Errorf("got %q\nwant %q", got, want)
	}
}

// TestApplyEditsMixesHashlineAndLegacy guards the two addressing modes sharing
// one call: hashline edits and legacy exact anchors must not interfere.
func TestApplyEditsMixesHashlineAndLegacy(t *testing.T) {
	got, err := applyEdits(hashlineSample, []editPair{
		{Hash: hl("beta"), NewText: "BETA"},
		{OldText: strptr("gamma"), NewText: "GAMMA"},
	})
	want := "alpha\nBETA\nGAMMA\nduplicate\nduplicate\n"
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != want {
		t.Errorf("got %q\nwant %q", got, want)
	}

	// A hash edit with no oldText and an empty oldText without hash are both rejected.
	if _, err := applyEdits(hashlineSample, []editPair{{NewText: "x"}}); err == nil {
		t.Error("expected an error for an edit with neither hash nor oldText")
	}
}

// TestApplyHashlineMatchesExtension is a compact end-to-end parity check: these
// (content, edit, result) triples are asserted identically by the TypeScript
// suite in pi-extension/hashline.test.ts.
func TestApplyHashlineMatchesExtension(t *testing.T) {
	cases := []struct {
		in    string
		edit  hashlineEdit
		want  string
		subok string
	}{
		{"alpha\nbeta\ngamma\nbeta\n", hashlineEdit{Hash: hl("alpha"), NewText: "ALPHA"}, "ALPHA\nbeta\ngamma\nbeta\n", ""},
		{"alpha\nbeta\ngamma\nbeta\n", hashlineEdit{Hash: hl("beta"), NewText: "BETA"}, "", "ambiguous"},
		{"alpha\nbeta\ngamma\nbeta\n", hashlineEdit{Hash: hl("alpha"), EndHash: hl("gamma"), NewText: "x\ny"}, "x\ny\nbeta\n", ""},
		{"alpha\nbeta\ngamma\nbeta\n", hashlineEdit{Hash: hl("gamma"), NewText: ""}, "alpha\nbeta\nbeta\n", ""},
		{"alpha\nbeta\ngamma\nbeta\n", hashlineEdit{Hash: hl("alpha"), Insert: "after", NewText: "a1\na2\na3"},
			"alpha\na1\na2\na3\nbeta\ngamma\nbeta\n", ""},
	}
	for i, tc := range cases {
		got, err := applyHashlineEdit(tc.in, tc.edit, 1)
		if tc.subok != "" {
			if err == nil || !strings.Contains(err.Error(), tc.subok) {
				t.Errorf("case %d: error = %v, want it to contain %q", i, err, tc.subok)
			}
			continue
		}
		if err != nil || got != tc.want {
			t.Errorf("case %d: got %q (%v), want %q", i, got, err, tc.want)
		}
	}
}

// TestHashlineApprovalCarriesResolvedDiff is the end-to-end check of the wire
// contract: a hashline proposal from the extension becomes an approval whose
// diff already shows the anchored line replaced — the user approves the bytes
// the extension will write, not an approximation of them.
func TestHashlineApprovalCarriesResolvedDiff(t *testing.T) {
	engine, err := NewEngine(EngineConfig{ConfigDir: t.TempDir(), Emit: func(any) {}})
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	const oldLine = "\tprintln(\"old\")"
	const original = "package main\n\nfunc main() {\n" + oldLine + "\n}\n"
	if err := os.WriteFile(filepath.Join(workspace, "main.go"), []byte(original), 0o644); err != nil {
		t.Fatal(err)
	}
	engine.state.workspacePath = workspace

	feedNorm(engine, "extension_ui_request", hashlineUIRequest(t, "ui-1", map[string]any{
		"toolCallId": "tc-1",
		"path":       "main.go",
		"what":       "Change the greeting",
		"why":        "the old one embarrassed us",
		"edits": []map[string]any{{
			"hash":    hashLine(oldLine, hashMinLength),
			"newText": "\tprintln(\"new\")",
		}},
	}))

	if len(engine.state.approvals) != 1 {
		t.Fatalf("expected one approval, got %d", len(engine.state.approvals))
	}
	appr := engine.state.approvals[0]
	if appr.Kind != protocol.ApprovalKindProposeEdit || appr.Path != "main.go" {
		t.Fatalf("unexpected approval: %+v", appr)
	}
	if !strings.Contains(appr.Diff, "-"+oldLine) || !strings.Contains(appr.Diff, "+\tprintln(\"new\")") {
		t.Fatalf("diff does not show the anchored line replaced:\n%s", appr.Diff)
	}
	if strings.Contains(appr.Diff, "-package main") {
		t.Fatalf("diff must not touch unanchored lines:\n%s", appr.Diff)
	}
}

// An unresolvable hash must never render a misleading diff. The extension
// refuses such a proposal before asking the user, but the backend is not the
// only thing that can be wrong: if it cannot resolve an anchor, the approval
// says so in words instead of showing an empty or partial diff.
func TestHashlineUnresolvableDiffSaysSo(t *testing.T) {
	engine, err := NewEngine(EngineConfig{ConfigDir: t.TempDir(), Emit: func(any) {}})
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err := os.WriteFile(filepath.Join(workspace, "main.go"), []byte("package main\n\nvar x = 1\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	engine.state.workspacePath = workspace

	feedNorm(engine, "extension_ui_request", hashlineUIRequest(t, "ui-2", map[string]any{
		"toolCallId": "tc-2",
		"path":       "main.go",
		"what":       "w",
		"why":        "y",
		"edits":      []map[string]any{{"hash": "0000", "newText": "var x = 2"}},
	}))

	if len(engine.state.approvals) != 1 {
		t.Fatalf("expected one approval, got %d", len(engine.state.approvals))
	}
	if diff := engine.state.approvals[0].Diff; !strings.Contains(diff, "could not render diff") || !strings.Contains(diff, "no line matches") {
		t.Fatalf("expected an explicit failure note in the diff, got:\n%s", diff)
	}
}

// hashlineUIRequest builds the extension_ui_request envelope pi writes for a
// coconut://propose_edit confirmation; `message` is the JSON string the
// extension passes to ctx.ui.confirm.
func hashlineUIRequest(t *testing.T, id string, message map[string]any) string {
	t.Helper()
	raw, err := json.Marshal(message)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := json.Marshal(map[string]any{
		"type":    "extension_ui_request",
		"id":      id,
		"method":  "confirm",
		"title":   "coconut://propose_edit",
		"message": string(raw),
	})
	if err != nil {
		t.Fatal(err)
	}
	return string(envelope)
}
